/* Built by tools/build-atlas.py — do not edit. The drawing of MAPS.persim (Lesion Atlas). */
(window.DYNDATA=window.DYNDATA||{})["persim"]={"kinds":{"cmp":["tell","--dk5"],"imp":["imp","--dk9"],"good":["good","--ok"],"bad":["bad","--bad"]},"groups":[["tell","Tell apart"],["imp","Impulse or feeling"],["good","All good"],["bad","All bad"]],"switches":[{"id":"pd","label":"Pick one","type":"one","options":[["par","Paranoid","clustera"],["szd","Schizoid","clustera"],["szt","Schizotypal","clustera"],["asp","Antisocial","antisocial"],["bpd","Borderline","borderline"],["his","Histrionic","clusterb"],["nar","Narcissistic","clusterb"],["avd","Avoidant","clusterc"],["dep","Dependent","clusterc"],["ocpd","OCPD","clusterc"],["ocd","OCD (vs OCPD)","ocd"],["cond","Conduct disorder","conductodd"],["split","Splitting","egodefenses"],["proj","Projection","egodefenses"],["act","Acting out","egodefenses"],["sub","Sublimation","egodefenses"]],"sections":[["Cluster A",["par","szd","szt"]],["Cluster B",["asp","bpd","his","nar"]],["Cluster C",["avd","dep","ocpd"]],["Look-alikes",["ocd","cond"]],["Defenses",["split","proj","act","sub"]]]}],"notes":{"":"Personality disorders are inflexible, pervasive patterns that are usually ego-syntonic — the person rarely sees a problem. Pick one: it lights with its look-alike, the line between them carries the tell, and the case card fills in.","pd:par":"Paranoid PD: pervasive distrust and suspicion, grudges, doubts about a partner’s fidelity — through projection. No fixed delusions (vs delusional disorder) and no hallucinations (vs schizophrenia). Psychotherapy: straightforward, professional, honest about mistakes.","pd:szd":"Schizoid PD: a loner by choice — constricted affect, indifferent to praise or criticism, an inner life of fantasy. Avoidant PD is just as isolated but wants relationships; schizotypal adds odd thinking.","pd:szt":"Schizotypal PD: odd beliefs, magical thinking, ideas of reference, eccentric appearance — on the schizophrenia spectrum. Any psychotic symptoms are brief and fragmentary; sustained psychosis means schizophrenia.","pd:asp":"Antisocial PD: disregard for others’ rights without remorse — lying, impulsivity, aggression, crime. It needs age ≥ 18 with conduct disorder before 15; under 18 the diagnosis is conduct disorder. Reward-based programs beat CBT.","pd:bpd":"Borderline PD: unstable mood, self-image and relationships, fear of abandonment, self-harm and emptiness, with splitting as the major defense. Mood disorders lack those core features. Dialectical behavior therapy is first line.","pd:his":"Histrionic PD: attention-seeking, dramatic, shallow and labile emotion, sexually provocative — defended by repression and dissociation. Suicide attempts and identity diffusion point to borderline instead.","pd:nar":"Narcissistic PD: grandiosity, entitlement, need for admiration, no empathy — and rage at criticism over a fragile self-esteem. Grandiosity that comes in episodes with euphoria and impairment is mania.","pd:avd":"Avoidant PD: hypersensitive to rejection, timid, feels inadequate — but wants relationships (schizoid does not). Social anxiety disorder fears specific situations rather than contact in general; the two can co-occur.","pd:dep":"Dependent PD: clingy, submissive, cannot decide alone, and often stays with an abusive partner. Close to avoidant, but the fear of abandonment is greater. Treatment is often successful (assertiveness, insight-oriented, group).","pd:ocpd":"Obsessive-compulsive PD: order, rules, perfection and control, ego-syntonic — the patient thinks the rules are right. Defenses: isolation of affect, intellectualization, reaction formation, undoing. CBT.","pd:ocd":"OCD is not a personality disorder: genuine obsessions and compulsions the patient finds unwanted (ego-dystonic). OCPD has the perfectionism without them. OCD: CBT and SSRIs, clomipramine second line.","pd:cond":"Conduct disorder: repeated aggression, destruction, theft or deceit in a child or adolescent. After 18 it is often reclassified as antisocial PD — which needs conduct disorder before 15. Psychotherapy (CBT).","pd:split":"Splitting: people are all good or all bad at different times — the borderline patient idealizes some staff and disparages others. Staff discuss it together and gently confront: no one is all good or all bad.","pd:proj":"Projection: one’s own unacceptable impulse is attributed to someone else — the man who wants to cheat accuses his wife. Typical of paranoid PD; meet it with honesty, not argument.","pd:act":"Acting out: a conflict is discharged in action instead of words or feelings — skipping therapy after a painful session, tantrums. The patient has lost control; get their attention first.","pd:sub":"Sublimation, a mature defense: an unacceptable wish becomes a similar, socially acceptable action — aggression channeled into sport. Reaction formation, by contrast, turns the feeling into its opposite."},"shapes":["<rect class=\"dyn-soft\" x=\"140\" y=\"110\" width=\"2200\" height=\"510\" rx=\"28\"/>",{"text":"Three clusters — pick one: it lights up with its look-alike, and the case card below fills in","x":170,"y":150,"cls":"dyn-big"},{"text":"Personality disorders: inflexible, pervasive patterns, usually ego-syntonic, present by early adulthood (First Aid p. 582)","x":170,"y":172,"cls":"dyn-cap"},{"text":"Results: ↑ present or needed · ↓ absent or not needed · ↔ either way","x":170,"y":194,"cls":"dyn-cap"},"<rect x=\"150\" y=\"214\" width=\"710\" height=\"396\" rx=\"20\" style=\"fill:none;stroke:var(--line-2);stroke-width:2\"/>",{"text":"Cluster A — weird","x":170,"y":248,"cls":"dyn-big"},{"text":"odd, eccentric · genetic link to schizophrenia","x":170,"y":270,"cls":"dyn-cap"},"<rect x=\"875\" y=\"214\" width=\"735\" height=\"396\" rx=\"20\" style=\"fill:none;stroke:var(--line-2);stroke-width:2\"/>",{"text":"Cluster B — wild","x":895,"y":248,"cls":"dyn-big"},{"text":"dramatic, erratic · mood and substance use disorders","x":895,"y":270,"cls":"dyn-cap"},"<rect x=\"1625\" y=\"214\" width=\"705\" height=\"396\" rx=\"20\" style=\"fill:none;stroke:var(--line-2);stroke-width:2\"/>",{"text":"Cluster C — worried","x":1645,"y":248,"cls":"dyn-big"},{"text":"anxious, fearful · anxiety disorders","x":1645,"y":270,"cls":"dyn-cap"},"<rect class=\"dyn-soft\" x=\"140\" y=\"640\" width=\"2200\" height=\"172\" rx=\"28\"/>",{"text":"Look-alikes outside the personality disorders","x":170,"y":676,"cls":"dyn-big"},{"svg":"<rect x=\"158\" y=\"290\" width=\"694\" height=\"60\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:par","pd:proj"]},{"text":"▶ this one","x":170,"y":324,"cls":"nf-l2 dyn-tag","when":["pd:par"]},{"text":"uses it","x":170,"y":324,"cls":"nf-l2","when":["pd:proj"]},{"svg":"<rect x=\"158\" y=\"370\" width=\"694\" height=\"60\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:szt"]},{"text":"▶ this one","x":170,"y":404,"cls":"nf-l2 dyn-tag","when":["pd:szt"]},{"svg":"<rect x=\"158\" y=\"450\" width=\"694\" height=\"60\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:szd","pd:avd"]},{"text":"▶ this one","x":170,"y":484,"cls":"nf-l2 dyn-tag","when":["pd:szd"]},{"text":"look-alike","x":170,"y":484,"cls":"nf-l2","when":["pd:avd"]},{"svg":"<rect x=\"883\" y=\"290\" width=\"719\" height=\"60\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:bpd","pd:his"]},{"text":"▶ this one","x":895,"y":324,"cls":"nf-l2 dyn-tag","when":["pd:his"]},{"text":"look-alike","x":895,"y":324,"cls":"nf-l2","when":["pd:bpd"]},{"svg":"<rect x=\"883\" y=\"370\" width=\"719\" height=\"60\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:bpd","pd:his","pd:split","pd:act"]},{"text":"▶ this one","x":895,"y":404,"cls":"nf-l2 dyn-tag","when":["pd:bpd"]},{"text":"look-alike","x":895,"y":404,"cls":"nf-l2","when":["pd:his"]},{"text":"uses it","x":895,"y":404,"cls":"nf-l2","when":["pd:split","pd:act"]},{"svg":"<rect x=\"883\" y=\"450\" width=\"719\" height=\"60\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:nar"]},{"text":"▶ this one","x":895,"y":484,"cls":"nf-l2 dyn-tag","when":["pd:nar"]},{"svg":"<rect x=\"883\" y=\"530\" width=\"719\" height=\"60\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:asp","pd:cond"]},{"text":"▶ this one","x":895,"y":564,"cls":"nf-l2 dyn-tag","when":["pd:asp"]},{"text":"look-alike","x":895,"y":564,"cls":"nf-l2","when":["pd:cond"]},{"svg":"<rect x=\"1633\" y=\"290\" width=\"689\" height=\"60\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:ocpd","pd:ocd"]},{"text":"▶ this one","x":1645,"y":324,"cls":"nf-l2 dyn-tag","when":["pd:ocpd"]},{"text":"look-alike","x":1645,"y":324,"cls":"nf-l2","when":["pd:ocd"]},{"svg":"<rect x=\"1633\" y=\"370\" width=\"689\" height=\"60\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:dep"]},{"text":"▶ this one","x":1645,"y":404,"cls":"nf-l2 dyn-tag","when":["pd:dep"]},{"svg":"<rect x=\"1633\" y=\"450\" width=\"689\" height=\"60\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:szd","pd:avd","pd:dep"]},{"text":"▶ this one","x":1645,"y":484,"cls":"nf-l2 dyn-tag","when":["pd:avd"]},{"text":"look-alike","x":1645,"y":484,"cls":"nf-l2","when":["pd:szd","pd:dep"]},{"svg":"<rect x=\"158\" y=\"708\" width=\"344\" height=\"64\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:par"]},{"text":"look-alike","x":330,"y":798,"cls":"nf-l2","anchor":"middle","when":["pd:par"]},{"svg":"<rect x=\"518\" y=\"708\" width=\"344\" height=\"64\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:szt"]},{"text":"look-alike","x":690,"y":798,"cls":"nf-l2","anchor":"middle","when":["pd:szt"]},{"svg":"<rect x=\"878\" y=\"708\" width=\"344\" height=\"64\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:bpd","pd:nar"]},{"text":"look-alike","x":1050,"y":798,"cls":"nf-l2","anchor":"middle","when":["pd:bpd","pd:nar"]},{"svg":"<rect x=\"1238\" y=\"708\" width=\"344\" height=\"64\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:asp","pd:cond"]},{"text":"▶ this one","x":1410,"y":798,"cls":"nf-l2 dyn-tag","anchor":"middle","when":["pd:cond"]},{"text":"look-alike","x":1410,"y":798,"cls":"nf-l2","anchor":"middle","when":["pd:asp"]},{"svg":"<rect x=\"1598\" y=\"708\" width=\"344\" height=\"64\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:avd"]},{"text":"look-alike","x":1770,"y":798,"cls":"nf-l2","anchor":"middle","when":["pd:avd"]},{"svg":"<rect x=\"1958\" y=\"708\" width=\"344\" height=\"64\" rx=\"16\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:ocpd","pd:ocd"]},{"text":"▶ this one","x":2130,"y":798,"cls":"nf-l2 dyn-tag","anchor":"middle","when":["pd:ocd"]},{"text":"look-alike","x":2130,"y":798,"cls":"nf-l2","anchor":"middle","when":["pd:ocpd"]},{"svg":"<path d=\"M500 320 C190 330 190 700 330 740\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:par"]},{"svg":"<path d=\"M500 480 C560 640 1890 640 1950 480\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:szd"]},{"svg":"<path d=\"M500 400 C760 420 760 650 690 740\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:szt"]},{"svg":"<path d=\"M1300 575 C1400 610 1410 660 1410 740\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:asp"]},{"svg":"<path d=\"M1070 400 C930 420 930 680 1050 740\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:bpd"]},{"svg":"<path d=\"M1350 320 C1520 320 1520 400 1350 400\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:bpd"]},{"svg":"<path d=\"M1350 320 C1520 320 1520 400 1350 400\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:his"]},{"svg":"<path d=\"M1070 480 C960 500 960 690 1050 740\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:nar"]},{"svg":"<path d=\"M500 480 C560 640 1890 640 1950 480\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:avd"]},{"svg":"<path d=\"M1950 480 C1950 620 1770 620 1770 740\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:avd"]},{"svg":"<path d=\"M2100 400 C2250 400 2250 480 2100 480\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:dep"]},{"svg":"<path d=\"M2100 320 C2320 330 2320 640 2130 740\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:ocpd"]},{"svg":"<path d=\"M2100 320 C2320 330 2320 640 2130 740\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:ocd"]},{"svg":"<path d=\"M1300 575 C1400 610 1410 660 1410 740\" style=\"fill:none;stroke:var(--dk5);stroke-width:3;stroke-dasharray:9 7;opacity:.8\"/>","when":["pd:cond"]},"<rect class=\"dyn-soft\" x=\"140\" y=\"832\" width=\"2200\" height=\"250\" rx=\"28\"/>",{"text":"Pick a disorder or a defense — its case card fills in here","x":170,"y":870,"cls":"dyn-big","unless":["pd:*"]},{"text":"Each disorder lights its look-alike: the case card says how to tell them apart.","x":470,"y":940,"cls":"nf-l2","unless":["pd:*"]},{"text":"Cluster","x":170,"y":906,"cls":"nf-l1","when":["pd:*"]},{"text":"Core pattern","x":170,"y":940,"cls":"nf-l1","when":["pd:*"]},{"text":"Defense · tell-tale","x":170,"y":974,"cls":"nf-l1","when":["pd:*"]},{"text":"Look-alike — how to tell","x":170,"y":1008,"cls":"nf-l1","when":["pd:*"]},{"text":"Therapy · what to do","x":170,"y":1042,"cls":"nf-l1","when":["pd:*"]},{"text":"Paranoid personality disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:par"]},{"text":"A — odd, eccentric (\"weird\") · genetic link to schizophrenia","x":470,"y":906,"cls":"nf-l2","when":["pd:par"]},{"text":"Pervasive distrust and suspiciousness — reads hidden threats in others, holds grudges, doubts a partner’s fidelity","x":470,"y":940,"cls":"nf-l2","when":["pd:par"]},{"text":"Projection: attributes to others the impulses they cannot accept in themselves","x":470,"y":974,"cls":"nf-l2","when":["pd:par"]},{"text":"Delusional disorder has fixed delusions — paranoid PD does not · schizophrenia adds hallucinations or thought disorder","x":470,"y":1008,"cls":"nf-l2","when":["pd:par"]},{"text":"Psychotherapy is the treatment of choice — straightforward and professional, not overly warm; admit mistakes honestly","x":470,"y":1042,"cls":"nf-l2","when":["pd:par"]},{"text":"Schizoid personality disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:szd"]},{"text":"A — odd, eccentric (\"weird\") · genetic link to schizophrenia","x":470,"y":906,"cls":"nf-l2","when":["pd:szd"]},{"text":"Lifelong social withdrawal by preference — solitary pursuits, constricted affect, indifferent to praise or criticism","x":470,"y":940,"cls":"nf-l2","when":["pd:szd"]},{"text":"Withdrawal and fantasy: an inner, imaginary life — the aloofness rests on a fear of intimacy","x":470,"y":974,"cls":"nf-l2","when":["pd:szd"]},{"text":"Avoidant PD wants relationships but fears rejection; schizoid prefers to be alone · schizotypal adds odd thinking","x":470,"y":1008,"cls":"nf-l2","when":["pd:szd"]},{"text":"Psychotherapy as for paranoid PD; in group therapy they may stay silent, yet the group can become their only social contact","x":470,"y":1042,"cls":"nf-l2","when":["pd:szd"]},{"text":"Schizotypal personality disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:szt"]},{"text":"A — odd, eccentric (\"weird\") · genetic link to schizophrenia · on the schizophrenia spectrum","x":470,"y":906,"cls":"nf-l2","when":["pd:szt"]},{"text":"Eccentric appearance, odd beliefs or magical thinking, ideas of reference, odd speech, few if any close friends","x":470,"y":940,"cls":"nf-l2","when":["pd:szt"]},{"text":"Under stress: brief psychotic symptoms — then back to the baseline oddness","x":470,"y":974,"cls":"nf-l2","when":["pd:szt"]},{"text":"Schizophrenia has sustained psychosis; in schizotypal PD psychotic symptoms are absent or brief and fragmentary","x":470,"y":1008,"cls":"nf-l2","when":["pd:szt"]},{"text":"Psychotherapy — never ridicule or judge the odd beliefs; antipsychotics may help ideas of reference","x":470,"y":1042,"cls":"nf-l2","when":["pd:szt"]},{"text":"Antisocial personality disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:asp"]},{"text":"B — dramatic, emotional, erratic (\"wild\") · genetic link to mood and substance use disorders","x":470,"y":906,"cls":"nf-l2","when":["pd:asp"]},{"text":"Disregard for others’ rights without remorse — lies, impulsivity, aggression, criminality · males > females","x":470,"y":940,"cls":"nf-l2","when":["pd:asp"]},{"text":"A charming, credible veneer — a stress interview confronting inconsistencies may reveal the hostility beneath","x":470,"y":974,"cls":"nf-l2","when":["pd:asp"]},{"text":"Conduct disorder is the same pattern under 18 · antisocial PD needs age ≥ 18 with conduct disorder before 15","x":470,"y":1008,"cls":"nf-l2","when":["pd:asp"]},{"text":"Limited evidence: contingency management and other reward-based programs work better than CBT","x":470,"y":1042,"cls":"nf-l2","when":["pd:asp"]},{"text":"Borderline personality disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:bpd"]},{"text":"B — dramatic, emotional, erratic (\"wild\") · genetic link to mood and substance use disorders","x":470,"y":906,"cls":"nf-l2","when":["pd:bpd"]},{"text":"Unstable mood, self-image and relationships, fear of abandonment, impulsivity, self-mutilation, suicidality, emptiness · F > M","x":470,"y":940,"cls":"nf-l2","when":["pd:bpd"]},{"text":"Splitting (all good or all bad) · projective identification · labile transferences; acts out impulses in therapy","x":470,"y":974,"cls":"nf-l2","when":["pd:bpd"]},{"text":"Bipolar or depressive disorder lacks the abandonment fear, splitting, emptiness and identity diffusion · histrionic: fewer suicide attempts","x":470,"y":1008,"cls":"nf-l2","when":["pd:bpd"]},{"text":"Dialectical behavior therapy (the most evidence); drugs for target symptoms only — avoid benzodiazepines","x":470,"y":1042,"cls":"nf-l2","when":["pd:bpd"]},{"text":"Histrionic personality disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:his"]},{"text":"B — dramatic, emotional, erratic (\"wild\") · genetic link to mood and substance use disorders","x":470,"y":906,"cls":"nf-l2","when":["pd:his"]},{"text":"Attention-seeking, dramatic speech and emotion, shallow labile affect, sexually provocative, uses appearance to draw attention","x":470,"y":940,"cls":"nf-l2","when":["pd:his"]},{"text":"Repression and dissociation: unaware of their true feelings; reality testing slips under stress","x":470,"y":974,"cls":"nf-l2","when":["pd:his"]},{"text":"Borderline PD: suicide attempts, identity diffusion and brief psychotic episodes are more likely there","x":470,"y":1008,"cls":"nf-l2","when":["pd:his"]},{"text":"Psychoanalytically oriented psychotherapy — clarifying their real feelings","x":470,"y":1042,"cls":"nf-l2","when":["pd:his"]},{"text":"Narcissistic personality disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:nar"]},{"text":"B — dramatic, emotional, erratic (\"wild\") · genetic link to mood and substance use disorders","x":470,"y":906,"cls":"nf-l2","when":["pd:nar"]},{"text":"Grandiosity and entitlement, needs admiration, lacks empathy, envious; demands the best · fragile self-esteem","x":470,"y":940,"cls":"nf-l2","when":["pd:nar"]},{"text":"Criticism → rage or defensiveness; blows to self-esteem → depressed mood, dysthymia or major depression","x":470,"y":974,"cls":"nf-l2","when":["pd:nar"]},{"text":"Mania: its grandiosity comes in episodes, with euphoria and functional impairment · borderline: more anxiety, more chaos","x":470,"y":1008,"cls":"nf-l2","when":["pd:nar"]},{"text":"Hard to treat: psychoanalytic approaches or group therapy; lithium for mood swings, serotonergic antidepressants","x":470,"y":1042,"cls":"nf-l2","when":["pd:nar"]},{"text":"Avoidant personality disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:avd"]},{"text":"C — anxious, fearful (\"worried\") · genetic link to anxiety disorders","x":470,"y":906,"cls":"nf-l2","when":["pd:avd"]},{"text":"Hypersensitive to rejection and criticism, socially inhibited, timid, feels inadequate — yet desires relationships","x":470,"y":940,"cls":"nf-l2","when":["pd:avd"]},{"text":"Needs a strong guarantee of uncritical acceptance; refusal of any request → withdraws and feels hurt","x":470,"y":974,"cls":"nf-l2","when":["pd:avd"]},{"text":"Schizoid PD wants to be alone · social anxiety disorder avoids specific situations, not contact in general — they may co-occur","x":470,"y":1008,"cls":"nf-l2","when":["pd:avd"]},{"text":"Psychotherapy built on alliance, group therapy, assertiveness training; β-blockers (atenolol) for autonomic arousal","x":470,"y":1042,"cls":"nf-l2","when":["pd:avd"]},{"text":"Dependent personality disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:dep"]},{"text":"C — anxious, fearful (\"worried\") · genetic link to anxiety disorders","x":470,"y":906,"cls":"nf-l2","when":["pd:dep"]},{"text":"Excessive need to be taken care of — clingy, submissive, cannot decide alone, low self-confidence","x":470,"y":940,"cls":"nf-l2","when":["pd:dep"]},{"text":"Tolerates an abusive or unfaithful partner to keep the attachment · in folie à deux, often the submissive partner","x":470,"y":974,"cls":"nf-l2","when":["pd:dep"]},{"text":"Avoidant PD is similar, but dependent fears abandonment more · borderline and histrionic depend on a series of people","x":470,"y":1008,"cls":"nf-l2","when":["pd:dep"]},{"text":"Often successful: insight-oriented, behavioral, assertiveness, family and group therapy","x":470,"y":1042,"cls":"nf-l2","when":["pd:dep"]},{"text":"Obsessive-compulsive personality disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:ocpd"]},{"text":"C — anxious, fearful (\"worried\") · genetic link to anxiety disorders","x":470,"y":906,"cls":"nf-l2","when":["pd:ocpd"]},{"text":"Preoccupied with order, rules, perfectionism and control — rigid, stubborn, indecisive, cannot delegate · ego-syntonic","x":470,"y":940,"cls":"nf-l2","when":["pd:ocpd"]},{"text":"Isolation of affect, intellectualization, rationalization, reaction formation, undoing","x":470,"y":974,"cls":"nf-l2","when":["pd:ocpd"]},{"text":"OCD: only OCD has genuine obsessions and compulsions, and the patient finds them unwanted (ego-dystonic)","x":470,"y":1008,"cls":"nf-l2","when":["pd:ocpd"]},{"text":"Cognitive or cognitive behavioral therapy; unlike most PDs, some seek help on their own","x":470,"y":1042,"cls":"nf-l2","when":["pd:ocpd"]},{"text":"Obsessive-compulsive disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:ocd"]},{"text":"Not a personality disorder — an obsessive-compulsive and related disorder","x":470,"y":906,"cls":"nf-l2","when":["pd:ocd"]},{"text":"Intrusive obsessions and/or compulsions that relieve the distress — the patient finds them unwanted (ego-dystonic)","x":470,"y":940,"cls":"nf-l2","when":["pd:ocd"]},{"text":"Associated with tic disorders; poor insight is linked to worse outcomes","x":470,"y":974,"cls":"nf-l2","when":["pd:ocd"]},{"text":"OCPD: order and perfectionism the patient agrees with — no genuine obsessions or compulsions","x":470,"y":1008,"cls":"nf-l2","when":["pd:ocd"]},{"text":"CBT and SSRIs; clomipramine and venlafaxine second line","x":470,"y":1042,"cls":"nf-l2","when":["pd:ocd"]},{"text":"Conduct disorder","x":170,"y":870,"cls":"dyn-big","when":["pd:cond"]},{"text":"Not a personality disorder — a disruptive behavior disorder of childhood","x":470,"y":906,"cls":"nf-l2","when":["pd:cond"]},{"text":"Repetitive aggression to people or animals, destruction of property, theft or deceit — ≥ 3 behaviors in the past 12 months","x":470,"y":940,"cls":"nf-l2","when":["pd:cond"]},{"text":"For some youth, a lifelong pattern culminating in antisocial PD — after 18 often reclassified","x":470,"y":974,"cls":"nf-l2","when":["pd:cond"]},{"text":"Antisocial PD needs age ≥ 18; conduct disorder is diagnosed after 18 only if antisocial PD criteria are not met","x":470,"y":1008,"cls":"nf-l2","when":["pd:cond"]},{"text":"Psychotherapy (eg, CBT)","x":470,"y":1042,"cls":"nf-l2","when":["pd:cond"]},{"text":"Splitting","x":170,"y":870,"cls":"dyn-big","when":["pd:split"]},{"text":"Immature defense — common in borderline personality disorder","x":470,"y":906,"cls":"nf-l2","when":["pd:split"]},{"text":"Believes people are all good or all bad at different times — an intolerance of ambiguity","x":470,"y":940,"cls":"nf-l2","when":["pd:split"]},{"text":"On a ward: idealizes some staff and disparages others — it can provoke the staff to turn against the patient","x":470,"y":974,"cls":"nf-l2","when":["pd:split"]},{"text":"Idealization keeps only the all-good half — extremely positive thoughts, the flaws ignored","x":470,"y":1008,"cls":"nf-l2","when":["pd:split"]},{"text":"Staff anticipate it, discuss it in meetings, and gently confront: no one is all good or all bad","x":470,"y":1042,"cls":"nf-l2","when":["pd:split"]},{"text":"Projection","x":170,"y":870,"cls":"dyn-big","when":["pd:proj"]},{"text":"Immature defense — typical of paranoid personality disorder","x":470,"y":906,"cls":"nf-l2","when":["pd:proj"]},{"text":"Attributes an unacceptable internal impulse to someone else","x":470,"y":940,"cls":"nf-l2","when":["pd:proj"]},{"text":"Wants to be unfaithful → accuses the spouse of cheating","x":470,"y":974,"cls":"nf-l2","when":["pd:proj"]},{"text":"Displacement redirects the feeling onto a neutral person or object; projection relocates the impulse itself","x":470,"y":1008,"cls":"nf-l2","when":["pd:proj"]},{"text":"Admit even minor mistakes; never argue or confront — counterprojection credits the patient’s feelings","x":470,"y":1042,"cls":"nf-l2","when":["pd:proj"]},{"text":"Acting out","x":170,"y":870,"cls":"dyn-big","when":["pd:act"]},{"text":"Immature defense — borderline patients act out their impulses in therapy","x":470,"y":906,"cls":"nf-l2","when":["pd:act"]},{"text":"Copes with a stressor or conflict through action instead of reflection or feelings","x":470,"y":940,"cls":"nf-l2","when":["pd:act"]},{"text":"Skips the next therapy session after a painful one · tantrums, apparently motiveless assaults","x":470,"y":974,"cls":"nf-l2","when":["pd:act"]},{"text":"Passive aggression shows hostility indirectly (repeatedly late) — acting out is direct action","x":470,"y":1008,"cls":"nf-l2","when":["pd:act"]},{"text":"The patient has lost control: first get their attention; if frightened, leave and call for help","x":470,"y":1042,"cls":"nf-l2","when":["pd:act"]},{"text":"Sublimation","x":170,"y":870,"cls":"dyn-big","when":["pd:sub"]},{"text":"Mature defense — mature adults wear a SASH: sublimation, altruism, suppression, humor","x":470,"y":906,"cls":"nf-l2","when":["pd:sub"]},{"text":"Replaces an unacceptable wish with a similar course of action that is socially acceptable","x":470,"y":940,"cls":"nf-l2","when":["pd:sub"]},{"text":"Aggression toward demanding parents channeled into excelling at sports","x":470,"y":974,"cls":"nf-l2","when":["pd:sub"]},{"text":"Reaction formation replaces the feeling with its opposite (overprotecting a resented child) — sublimation keeps the drive","x":470,"y":1008,"cls":"nf-l2","when":["pd:sub"]},{"text":"A mature defense — nothing to undo","x":470,"y":1042,"cls":"nf-l2","when":["pd:sub"]},"<rect class=\"dyn-soft\" x=\"140\" y=\"1102\" width=\"2200\" height=\"384\" rx=\"28\"/>",{"text":"Defenses in play — what each one does with an unwanted feeling (First Aid pp. 570–571)","x":170,"y":1140,"cls":"dyn-big"},{"text":"immature: splitting, projection, acting out · mature: sublimation (SASH) · borderline lights splitting, paranoid lights projection","x":170,"y":1162,"cls":"dyn-cap"},"<rect x=\"150\" y=\"1180\" width=\"530\" height=\"296\" rx=\"20\" style=\"fill:none;stroke:var(--line-2);stroke-width:2\"/>",{"svg":"<rect x=\"150\" y=\"1180\" width=\"530\" height=\"296\" rx=\"20\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:split","pd:bpd"]},"<rect x=\"700\" y=\"1180\" width=\"530\" height=\"296\" rx=\"20\" style=\"fill:none;stroke:var(--line-2);stroke-width:2\"/>",{"svg":"<rect x=\"700\" y=\"1180\" width=\"530\" height=\"296\" rx=\"20\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:proj","pd:par"]},"<rect x=\"1250\" y=\"1180\" width=\"530\" height=\"296\" rx=\"20\" style=\"fill:none;stroke:var(--line-2);stroke-width:2\"/>",{"svg":"<rect x=\"1250\" y=\"1180\" width=\"530\" height=\"296\" rx=\"20\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:act"]},"<rect x=\"1800\" y=\"1180\" width=\"530\" height=\"296\" rx=\"20\" style=\"fill:none;stroke:var(--line-2);stroke-width:2\"/>",{"svg":"<rect x=\"1800\" y=\"1180\" width=\"530\" height=\"296\" rx=\"20\" style=\"fill:var(--accent);fill-opacity:.10;stroke:var(--accent);stroke-opacity:.55;stroke-width:2\"/>","when":["pd:sub"]},"<circle cx=\"410\" cy=\"1323\" r=\"12\" style=\"fill:var(--surface);stroke:var(--ink-2);stroke-width:3\"/><path d=\"M410 1335 V1367 M394 1347 H426 M410 1367 L398 1389 M410 1367 L422 1389\" style=\"stroke:var(--ink-2);stroke-width:3;fill:none;stroke-linecap:round\"/><circle cx=\"230\" cy=\"1278\" r=\"12\" style=\"fill:var(--surface);stroke:var(--ink-2);stroke-width:3\"/><path d=\"M230 1290 V1322 M214 1302 H246 M230 1322 L218 1344 M230 1322 L242 1344\" style=\"stroke:var(--ink-2);stroke-width:3;fill:none;stroke-linecap:round\"/><circle cx=\"230\" cy=\"1368\" r=\"12\" style=\"fill:var(--surface);stroke:var(--ink-2);stroke-width:3\"/><path d=\"M230 1380 V1412 M214 1392 H246 M230 1412 L218 1434 M230 1412 L242 1434\" style=\"stroke:var(--ink-2);stroke-width:3;fill:none;stroke-linecap:round\"/><circle cx=\"590\" cy=\"1278\" r=\"12\" style=\"fill:var(--surface);stroke:var(--ink-2);stroke-width:3\"/><path d=\"M590 1290 V1322 M574 1302 H606 M590 1322 L578 1344 M590 1322 L602 1344\" style=\"stroke:var(--ink-2);stroke-width:3;fill:none;stroke-linecap:round\"/><circle cx=\"590\" cy=\"1368\" r=\"12\" style=\"fill:var(--surface);stroke:var(--ink-2);stroke-width:3\"/><path d=\"M590 1380 V1412 M574 1392 H606 M590 1412 L578 1434 M590 1412 L602 1434\" style=\"stroke:var(--ink-2);stroke-width:3;fill:none;stroke-linecap:round\"/>",{"text":"all good","x":230,"y":1258,"cls":"nf-l1","anchor":"middle"},{"text":"all bad","x":590,"y":1258,"cls":"nf-l1","anchor":"middle"},{"text":"patient","x":410,"y":1412,"cls":"nf-l2","anchor":"middle"},{"text":"the same staff, sorted into all good or all bad","x":170,"y":1462,"cls":"dyn-cap","when":["pd:split","pd:bpd"]},"<circle cx=\"800\" cy=\"1323\" r=\"12\" style=\"fill:var(--surface);stroke:var(--ink-2);stroke-width:3\"/><path d=\"M800 1335 V1367 M784 1347 H816 M800 1367 L788 1389 M800 1367 L812 1389\" style=\"stroke:var(--ink-2);stroke-width:3;fill:none;stroke-linecap:round\"/><circle cx=\"1130\" cy=\"1323\" r=\"12\" style=\"fill:var(--surface);stroke:var(--ink-2);stroke-width:3\"/><path d=\"M1130 1335 V1367 M1114 1347 H1146 M1130 1367 L1118 1389 M1130 1367 L1142 1389\" style=\"stroke:var(--ink-2);stroke-width:3;fill:none;stroke-linecap:round\"/><ellipse cx=\"880\" cy=\"1268\" rx=\"80\" ry=\"24\" style=\"fill:var(--surface);stroke:var(--ink-3);stroke-width:2.5\"/><circle cx=\"826\" cy=\"1302\" r=\"6\" style=\"fill:var(--surface);stroke:var(--ink-3);stroke-width:2\"/>",{"text":"my own impulse","x":880,"y":1272,"cls":"nf-l2","anchor":"middle"},{"text":"self","x":800,"y":1412,"cls":"nf-l2","anchor":"middle"},{"text":"someone else","x":1130,"y":1412,"cls":"nf-l2","anchor":"middle"},{"text":"the impulse is attributed to the other person","x":720,"y":1462,"cls":"dyn-cap","when":["pd:proj","pd:par"]},"<rect x=\"1270\" y=\"1322\" width=\"165\" height=\"50\" rx=\"12\" style=\"fill:var(--surface);stroke:var(--ink-3);stroke-width:2.5\"/><rect x=\"1455\" y=\"1236\" width=\"170\" height=\"50\" rx=\"12\" style=\"fill:var(--surface);stroke:var(--ink-3);stroke-width:2.5;stroke-dasharray:7 6\"/><rect x=\"1640\" y=\"1322\" width=\"120\" height=\"50\" rx=\"12\" style=\"fill:var(--surface);stroke:var(--ink-3);stroke-width:2.5\"/><path d=\"M1395 1322 L1475 1288 M1610 1288 L1690 1322\" style=\"fill:none;stroke:var(--ink-3);stroke-width:2.5;stroke-dasharray:6 6\"/>",{"text":"painful feeling","x":1352,"y":1352,"cls":"nf-l1","anchor":"middle"},{"text":"words · reflection","x":1540,"y":1266,"cls":"nf-l1","anchor":"middle"},{"text":"action","x":1700,"y":1352,"cls":"nf-l1","anchor":"middle"},{"svg":"<path d=\"M1423 1293 L1447 1317 M1447 1293 L1423 1317\" style=\"fill:none;stroke:var(--bad);stroke-width:4;stroke-linecap:round\"/>","when":["pd:act"]},{"text":"the reflection is skipped","x":1540,"y":1306,"cls":"nf-l2","anchor":"middle","when":["pd:act"]},{"text":"feeling straight into action — skips the next session","x":1270,"y":1462,"cls":"dyn-cap","when":["pd:act"]},"<rect x=\"1820\" y=\"1322\" width=\"180\" height=\"50\" rx=\"12\" style=\"fill:var(--surface);stroke:var(--ink-3);stroke-width:2.5\"/><rect x=\"2130\" y=\"1322\" width=\"180\" height=\"50\" rx=\"12\" style=\"fill:var(--surface);stroke:var(--ink-3);stroke-width:2.5\"/>",{"text":"unacceptable wish","x":1910,"y":1352,"cls":"nf-l1","anchor":"middle"},{"text":"acceptable outlet","x":2220,"y":1352,"cls":"nf-l1","anchor":"middle"},{"text":"aggression","x":1910,"y":1398,"cls":"nf-l2","anchor":"middle"},{"text":"excelling at sports","x":2220,"y":1398,"cls":"nf-l2","anchor":"middle"},{"text":"the same drive, a socially acceptable form","x":1820,"y":1462,"cls":"dyn-cap","when":["pd:sub"]}],"flows":[{"d":"M500 320 C190 330 190 700 330 740","len":560,"speed":150,"r":6,"when":["pd:par"],"base":{"cmp":4}},{"d":"M500 480 C560 640 1890 640 1950 480","len":1600,"speed":150,"r":6,"when":["pd:szd"],"base":{"cmp":10}},{"d":"M500 400 C760 420 760 650 690 740","len":460,"speed":150,"r":6,"when":["pd:szt"],"base":{"cmp":3}},{"d":"M1300 575 C1400 610 1410 660 1410 740","len":230,"speed":150,"r":6,"when":["pd:asp"],"base":{"cmp":3}},{"d":"M1070 400 C930 420 930 680 1050 740","len":440,"speed":150,"r":6,"when":["pd:bpd"],"base":{"cmp":3}},{"d":"M1350 320 C1520 320 1520 400 1350 400","len":300,"speed":150,"r":6,"when":["pd:bpd"],"base":{"cmp":3}},{"d":"M1350 320 C1520 320 1520 400 1350 400","len":300,"speed":150,"r":6,"when":["pd:his"],"base":{"cmp":3}},{"d":"M1070 480 C960 500 960 690 1050 740","len":340,"speed":150,"r":6,"when":["pd:nar"],"base":{"cmp":3}},{"d":"M500 480 C560 640 1890 640 1950 480","len":1600,"speed":150,"r":6,"when":["pd:avd"],"base":{"cmp":10}},{"d":"M1950 480 C1950 620 1770 620 1770 740","len":320,"speed":150,"r":6,"when":["pd:avd"],"base":{"cmp":3}},{"d":"M2100 400 C2250 400 2250 480 2100 480","len":260,"speed":150,"r":6,"when":["pd:dep"],"base":{"cmp":3}},{"d":"M2100 320 C2320 330 2320 640 2130 740","len":620,"speed":150,"r":6,"when":["pd:ocpd"],"base":{"cmp":4}},{"d":"M2100 320 C2320 330 2320 640 2130 740","len":620,"speed":150,"r":6,"when":["pd:ocd"],"base":{"cmp":4}},{"d":"M1300 575 C1400 610 1410 660 1410 740","len":230,"speed":150,"r":6,"when":["pd:cond"],"base":{"cmp":3}},{"d":"M392 1338 L252 1302","len":150,"speed":90,"r":6,"unless":["pd:*"],"base":{"good":1}},{"d":"M392 1338 L252 1302","len":150,"speed":110,"r":7,"when":["pd:split","pd:bpd"],"base":{"good":3}},{"d":"M392 1352 L252 1388","len":150,"speed":90,"r":6,"unless":["pd:*"],"base":{"good":1}},{"d":"M392 1352 L252 1388","len":150,"speed":110,"r":7,"when":["pd:split","pd:bpd"],"base":{"good":3}},{"d":"M428 1338 L568 1302","len":150,"speed":90,"r":6,"unless":["pd:*"],"base":{"bad":1}},{"d":"M428 1338 L568 1302","len":150,"speed":110,"r":7,"when":["pd:split","pd:bpd"],"base":{"bad":3}},{"d":"M428 1352 L568 1388","len":150,"speed":90,"r":6,"unless":["pd:*"],"base":{"bad":1}},{"d":"M428 1352 L568 1388","len":150,"speed":110,"r":7,"when":["pd:split","pd:bpd"],"base":{"bad":3}},{"d":"M955 1276 C1020 1250 1080 1270 1118 1316","len":200,"speed":90,"r":6,"unless":["pd:*"],"base":{"imp":2}},{"d":"M955 1276 C1020 1250 1080 1270 1118 1316","len":200,"speed":120,"r":7,"when":["pd:proj","pd:par"],"base":{"imp":4}},{"d":"M1435 1347 H1640","len":205,"speed":90,"r":6,"unless":["pd:*"],"base":{"imp":2}},{"d":"M1435 1347 H1640","len":205,"speed":120,"r":7,"when":["pd:act"],"base":{"imp":4}},{"d":"M2000 1347 H2130","len":130,"speed":90,"r":6,"unless":["pd:*"],"base":{"imp":2}},{"d":"M2000 1347 H2130","len":130,"speed":120,"r":7,"when":["pd:sub"],"base":{"imp":3}}],"sites":[],"readouts":[{"l":"Ego-syntonic","mods":[{"when":["pd:par","pd:szd","pd:szt","pd:asp","pd:bpd","pd:his","pd:nar","pd:avd","pd:dep","pd:ocpd"],"d":1},{"when":["pd:ocd"],"d":-1}]},{"l":"Wants closeness","mods":[{"when":["pd:avd","pd:dep","pd:bpd","pd:szt"],"d":1},{"when":["pd:szd"],"d":-1}]},{"l":"Fears rejection or abandonment","mods":[{"when":["pd:avd","pd:dep","pd:bpd"],"d":1},{"when":["pd:szd"],"d":-1}]},{"l":"Odd thinking or perception","mods":[{"when":["pd:szt"],"d":1},{"when":["pd:par","pd:szd","pd:avd"],"d":-1}]},{"l":"Violates others’ rights","mods":[{"when":["pd:asp","pd:cond"],"d":1},{"when":["pd:nar","pd:his","pd:par"],"d":-1},{"when":["pd:bpd"],"d":0}]},{"l":"Needs age ≥ 18","mods":[{"when":["pd:asp"],"d":1},{"when":["pd:cond"],"d":-1}]},{"l":"Mature defense","mods":[{"when":["pd:sub"],"d":1},{"when":["pd:split","pd:proj","pd:act"],"d":-1}]}],"panel":{"x":2420,"y":110,"w":1000},"src":"OCOM Psych SDL 28–30 (Kaplan & Sadock ch 19, 23; Osmosis ch 98–100) · First Aid pp. 570–571, 574, 580, 582 · Kaplan & Sadock ch 2, 9"};
